// Event-to-command mapping with deduplication
function handleEvent(evt, state) {
  if (state.processed?.includes(evt.id)) return;

  const cmd = mapEventToCommand(evt);
  enqueueToOutbox(cmd);
  state.processed = [...(state.processed || []), evt.id];
